function  list_of_muscle3_settings = metis4muscle3_setting_list

% format ['name','muscle3_type',default_value,'comment'}
list_of_muscle3_settings = {
    {'metis_synchronization_reuse','int',0,'synchronisation on reuse_instance : METIS actor can be forced to be synchronised or not on reuse_instance state.'}, ...
    {'metis_synchronization_flush','int',0,'if =1, force buffer to be flushed when O_I ports are used to prevent workflow dead lock or message synchronisation porblemon some system with MUSCLE3'}, ...,
    {'metis_alwaysreadinitport','int',0,'if = 1, read also init ports on every iteration in addition of input ports, not only at initialisation'}, ...
    {'metis_updatetimeonrestart','int',0,'if =1, update time on restart with resuming message time stamp.'}, ...
    {'metis_clock_time_start','float',0,'initial time of the simulation in s (only needed in standalone use of METIS actor).'}, ...
    {'metis_clock_time_stop','float',Inf,'ending time in s: after this time, the actor will exit.'}, ...
    {'metis_clock_time_dt','float',3.14,'time step (s): used if no source of time is provide to the actor or if internal clock is used'}, ...
    {'metis_clock_internal','str','off','switch on or off  internal actor clock use'}, ...
    {'metis_usenexttimestamp','int',0,'if = 1, METIS compute for next_timestamp instead of timestamp.'}, ...
    {'metis_filename','str','','metis_filename: METIS file name (including full path) load for replay mode or interpolation mode if setting metis_computing is 0 and if pulse_schedule port is not connected.'}, ...
    {'metis_computation','int',1,'if = 0, METIS is not computed, data are interpolated and stream from METIS simulation file defined by setting metis_filename.'}, ...
    {'metis_workingpoint','int',0,'if = 1, METIS is run in working point mode for power plant design'}, ...
    {'metis_coldinit','int',0,'if = 1, METIS is initialized from METIS simulation file defined by setting metis_filename using interpolated data.'}, ...
    {'metis_idstime','int',0,'if = 1, external data will use time store in IDS instead of time stamp from MUSCLE3 message'}, ...
    {'metis_timeoffset','float',0,'offset between METIS internal time (time stamp in METIS output message) and input message time stamp or IDS time (s).'}, ...
    {'metis_psioffset','float',0,'polodial flux offset between METIS and external equilibrium psi_metis = cocos_sign * psi_equilibrium / (2*pi) - psioffset'}, ...
    {'metis_nbpts1d','int',101,'number of radial points in 1D profile used for external except for the equilibrium'}, ...
    {'metis_numberofequilibriumtimeslices','int',3,'number of external equilibrium time slices stored in METIS actor. The minimum is 3. Should be set to Inf if the workflow is intented to rewind. It has a impact on memory used by the actor.'}, ...
    {'metis_sawtooth_onoff','str','off','Turn on or off mechanism for mimicking sawtooth when METIS is used in link with NICE code solving Grad-Shafranov and diamagnetic function evolution (equivalent to current diffusion equation).'}, ...
    {'metis_sawtooth_nbtmin','int',3,'minimum number of time steps between two sawtooth triggers'}};